{
  "story": "Track a closed, warm-water cycle without ice, plants, or groundwater. Start with ocean water, then advance through evaporation, condensation, precipitation, and runoff. Sunlight enables evaporation; cooling forms cloud droplets; gravity returns water through rain and runoff. Compare the final reservoir masses with the start: phase and location change, but total water stays constant.",
  "aha": {
    "stateId": "returned",
    "observation": "Water changes phase and location during its cycle, but transfers between reservoirs leave the total water mass unchanged."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "cycle-rail",
      "kind": "step-rail",
      "presentation": "Reuse the approved card shell and canonical cycle composition. Keep explanation and instructions above the experiment, with progress confined to this rail. Capture the returned state as the reference evidence.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "water-reservoirs",
      "kind": "fixed-picture",
      "presentation": "Arrange four fixed, named regions in canonical cycle order, using the declared links. Highlight active regions and their connecting transfer link. Show phase names explicitly, without relying on color. Region sizes are schematic, not mass-scaled; reserve readable label space throughout.",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "links": "variant.links"
      }
    },
    {
      "id": "reservoir-explanation",
      "kind": "active-callout",
      "presentation": "Anchor text beside the target region, with consistent space in every state. Render reason as the bound status line. Callouts identify where and explain mechanisms; numerical values appear only in the ledger.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "water-mass-ledger",
      "kind": "value-readout",
      "presentation": "Use stable ledger rows labeled Water mass, in kilograms. Values are exact integers; no rounding applies. Compute total mass as M = O + V + C + L. The initial ocean mass and evaporated parcel mass are fixed by their respective ledger states. Every later transfer moves that same parcel intact. Count water only, excluding air; permit no outside water exchanges. Place the formula and measurement conventions above the experiment.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "cycle-state",
      "kind": "index",
      "items": "variant.states",
      "label": "Water cycle state",
      "presentation": "Navigation budget: one index control; parameter-control budget: zero. Default to the first state; advance one state within the first and last bounds. Use Previous and Next, retaining their names when disabled at boundaries. Every state persists until learner action, including returned; there is no autoplay. States represent transfers, not equal time intervals. Provide accessible button names, visible focus, and Left/Right keyboard operation."
    },
    {
      "id": "reset-cycle",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Provide visible focus, an accessible name, and Enter/Space activation."
    }
  ],
